UPDATE risk_knowledge_checks SET objective='Determine whether vector and embedding services prevent unauthorized access, enumeration, export and cross-namespace inference of sensitive records.', method='Using owner-authorised synthetic data and identities, test direct vector-service access, namespace isolation, metadata filters, similarity-query enumeration, export paths and cross-identity inference. Verify network and identity controls prevent unauthorized raw or inferable data exposure.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-045 assessed system, version, environment and scope for Vector and embedding services expose raw or inferable data","ARL-KB-045 control configuration or source location showing how reduce the likelihood and impact of vector and embedding services expose raw or inferable data and make the remaining risk visible.","ARL-KB-045 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-045 policy, authorization, tool or audit events proving whether the tested vector and embedding services expose raw or inferable data path executed","ARL-KB-045 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-045 passes only when “Vector and embedding services expose raw or inferable data” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-045 fails when weak access control, shared indexes or unrestricted similarity queries leak sensitive records or membership, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-045 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='d7ceb77c7bf3ccbbc32b3d0f558a29d74c5841200cd8b387ec54a9bc39700c51', updated_at='2026-08-06' WHERE entry_id='ARL-KB-045';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of vector and embedding services expose raw or inferable data and make the remaining risk visible.', recommended_remediation='Private-network and identity-protect vector services, minimise metadata, isolate indexes, rate limit queries and monitor bulk or probing behaviour.', default_owner='Data platform owner', priority='P1', implementation_principles_json='["ARL-KB-045: Protect vector and embedding services with explicit identity and network boundaries.","ARL-KB-045: Isolate indexes or namespaces and minimise stored or returned metadata.","ARL-KB-045: Rate-limit and monitor bulk, probing and inference-style query behaviour."]', monitoring='For ARL-KB-045, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-045 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-045: “Vector and embedding services expose raw or inferable data” is no longer reproducible against the exact remediated version.","ARL-KB-045: Authorised in-scope use completes successfully, remains within the documented asset scope for vector and embedding services expose raw or inferable data, and produces no unintended side effect.","ARL-KB-045: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-045: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='0ce3d464dafbf87fa66fc7d1f7ade2cf8c3b19e04c6266848fbbd26593e0072b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-045';
