UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Old permissions, prices, policies or customer facts remain active after they change.","customer_symptom":"A user or operator may observe old permissions, prices, policies or customer facts remain active after they change; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in old permissions, prices, policies or customer facts remain active after they change, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["memory or cache-enabled agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between memory or cache-enabled agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If old permissions, prices, policies or customer facts remain active after they change, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-047 memory, cache, vectorisation, summarisation or source-of-truth change","ARL-KB-047 freshness, invalidation, TTL or precedence-policy change","ARL-KB-047 stale-permission, stale-price, stale-policy or outdated-fact incident","ARL-KB-047 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='b91f8cef888993fb7e6459386fed8e7d567d079335526cc8bdfb1c3c9a0aedb6', updated_at='2026-08-06' WHERE id='ARL-KB-047';
