limitations='This bounded ARL-KB-047 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='03f5760a372f0db9975afb57d82f68a5673b5f3156a089e4720be01c9c7f63ae', updated_at='2026-08-06' WHERE entry_id='ARL-KB-047';
