UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind.","customer_symptom":"A user or operator may observe deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing personal data"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents processing personal data and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-048 retention, deletion, backup, provider-copy or derived-data flow change","ARL-KB-048 new embedding, summary, cache, export or evidence store","ARL-KB-048 deletion failure, retained-derived-data or rights-request incident","ARL-KB-048 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='4693772a0f2f243eb3771f6798cc6f7ff6e9f697b1d2c3f22d9c0d319cacfea2', updated_at='2026-08-06' WHERE id='ARL-KB-048';
